{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('WWW stripping regression', () => {
  it('should strip www from single-character second-level domain', () => {
    const input = 'http://www.a.com/';
    const expected = 'http://a.com';
    assert.strictEqual(normalizeUrl(input, {}), expected);
  });
});"}
